mapper.select:
select * from (SELECT REVEAL.ID id ,REVEAL.REP_ID repId ,REVEAL.REPORT_NAME reportName ,REVEAL.PROD_NAME prodName ,REVEAL.PRODID prodid ,case when REVEAL.START_DATE is null or REVEAL.START_DATE = REVEAL.END_DATE then to_char(REVEAL.END_DATE,'yyyy-mm-dd') else to_char(REVEAL.START_DATE,'yyyy-mm-dd') || '--'||to_char(REVEAL.END_DATE,'yyyy-mm-dd') end reportDate ,REVEAL.END_DATE endDate ,REVEAL.START_DATE startDate ,REVEAL.SYS_FILENAME sysFilename ,REVEAL.SYS_FILEPATH sysFilepath ,REVEAL.REVEAL_DATE revealDate /**披露日**/ ,REVEAL.FILEPATH filepath ,REVEAL.FILENAME filename ,REVEAL.CONFIRM_STATUS confirmStatus
,REVEAL.REVEAL_STATUS revealStatus
,REVEAL.STATUS status ,REVEAL.CREATE_USER createUser ,REVEAL.CREATE_DEPT createDept ,REVEAL.CREATE_TIME createTime ,REVEAL.UPDATE_USER updateUser ,REVEAL.UPDATE_TIME updateTime ,to_char(REVEAL.CREATE_TIME,'yyyy-MM-dd') createTimeStr ,to_char(REVEAL.CONFIRM_DATE,'yyyy-MM-dd') confirmDateStr ,REVEAL.SYS_FILEPATH seqno
,REVEAL.REVEAL_CHANNEL revealChannel ,REVEAL.IS_CONFIRM isConfirm ,REVEAL.IS_REVEAL isReveal
,REVEAL.DETAIL detail ,to_char(REVEAL.TIME,'yyyy-MM-dd') uploadTime ,REVEAL.CONFIRM_USER confirmUser ,REVEAL.REPORT_CATEGORY reportCategory ,rfp.NAME reportCategoryName ,to_char(REVEAL.REVEAL_END_DATE,'yyyy-mm-dd hh24:mi') revealEndDateStr ,REVEAL.ANNEX annex ,REVEAL.ANNEX_PATH annexPath /* 多级法人改造 需查询出fin_product.finprod_id字段 add by caojin 2020/6/9 start*/ ,fp.finprod_id finprodId /* 多级法人改造 需查询出fin_product.finprod_id字段 add by caojin 2020/6/9 end*/ FROM REP_REVEAL REVEAL left join rep_info info on REVEAL.rep_id = info.rep_id left join rep_ftp_path rfp on REVEAL.REPORT_CATEGORY = rfp.ID /* 多级法人改造 需查询出fin_product.finprod_id字段 add by caojin 2020/6/9 start*/ LEFT JOIN fin_product fp ON fp.FINPROD_MARKET_ID = REVEAL.PRODID /* 多级法人改造 需查询出fin_product.finprod_id字段 add by caojin 2020/6/9 end*/ where 1=1 and REVEAL.status ='E'/*有效*/ AND FP.P_FINPROD_ID IS NULL
AND decode(REVEAL.REVEAL_STATUS,null,'1',REVEAL.REVEAL_STATUS) = #{revealStatus,jdbcType=VARCHAR}
AND REVEAL.PRODID IN
#{item}
AND REVEAL.REPORT_NAME like '%'||#{reportName,jdbcType=VARCHAR}||'%'
AND to_char(REVEAL.CREATE_TIME,'yyyy-mm-dd') >= #{valDateBegin,jdbcType=VARCHAR}
AND to_char(REVEAL.CREATE_TIME,'yyyy-mm-dd') <= #{valDateEnd,jdbcType=VARCHAR}
AND decode(REVEAL.CONFIRM_STATUS,null,'02',REVEAL.CONFIRM_STATUS) = #{confirmStatus,jdbcType=VARCHAR}
AND to_char(REVEAL.CONFIRM_DATE,'yyyy-mm-dd') >= #{confirmDateBegin,jdbcType=VARCHAR}
AND to_char(REVEAL.CONFIRM_DATE,'yyyy-mm-dd') <= #{confirmDateEnd,jdbcType=VARCHAR}
AND REVEAL.IS_CONFIRM IN
#{item}
and(
REVEAL.REVEAL_CHANNEL like '%'||#{item}||'%'
)
AND to_char(REVEAL.REVEAL_DATE,'yyyy-mm-dd') >= #{revealDateBegin,jdbcType=VARCHAR}
AND to_char(REVEAL.REVEAL_DATE,'yyyy-mm-dd') <= #{revealDateEnd,jdbcType=VARCHAR}
AND to_char(REVEAL.REVEAL_END_DATE,'yyyy-mm-dd') >= #{revealEndDateBegin,jdbcType=VARCHAR}
AND to_char(REVEAL.REVEAL_END_DATE,'yyyy-mm-dd') <= #{revealEndDateEnd,jdbcType=VARCHAR}
AND REVEAL.REPORT_CATEGORY IN
#{item}
order by REVEAL.CONFIRM_STATUS ASC,
REVEAL.REVEAL_STATUS DESC,
REVEAL.CREATE_TIME DESC) where 1=1

mapper.update:
      update REP_REVEAL
      set 
      FILEPATH = #{filepath,jdbcType=VARCHAR}
      ,FILENAME = #{filename,jdbcType=VARCHAR}
      ,TIME = #{time,jdbcType=TIMESTAMP}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = sysdate
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      ANNEX_PATH = #{annexPath,jdbcType=VARCHAR}
      ,ANNEX = #{annex,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = sysdate
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      CONFIRM_STATUS = #{confirmStatus,jdbcType=VARCHAR},
      CONFIRM_DATE = #{confirmDate,jdbcType=DATE},
      CONFIRM_USER = #{confirmUser,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = sysdate

	  	,IS_REVEAL=#{isReveal,jdbcType=VARCHAR}


	  	,IS_CONFIRM=#{isConfirm,jdbcType=VARCHAR}

      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      REVEAL_STATUS = #{revealStatus,jdbcType=VARCHAR},
      REVEAL_DATE = #{revealDate,jdbcType=DATE},
      REVEAL_USER = #{revealUser,jdbcType=VARCHAR}

	  	,IS_REVEAL=#{isReveal,jdbcType=VARCHAR}

      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = sysdate
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      STATUS = #{status,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = sysdate
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

