	and bncf.val_bal_flag = #{valBalFlag}
	and bncf.val_date = #{valDate}
	and bfi.file_name = #{fileName}

   select bfi.FILE_ID from 
	  BOK_FILE_INFO  bfi 
	where bfi.file_type = #{fileType}
      and bfi.file_name = #{fileName}
      and bfi.file_path = #{filePath}

